    "contracts/vault/modules/aaveV3WstETHWeETHSwapModule/main.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity 0.8.17;

import "./events.sol";
import "../../common/variablesBufferHelper.sol";
import "../../common/helpers.sol";

contract AaveV3WstETHWeETHSwapModule is Events, VariablesBufferHelper, Helpers {
    /***********************************|
    |              ERRORS               |
    |__________________________________*/
    error AaveV3WstETHWeETHSwapModule__InvalidSwapConnector();
    error AaveV3WstETHWeETHSwapModule__SwapNotProfitable();

    /***********************************|
    |          SWAP CORE                |
    |__________________________________*/
    /// @notice Swaps wstETH to weETH
    /// @notice Assumes the position is wstETH/ETH
    /// @param wstEthSellAmount_ The amount of wstETH to sell
    /// @param unitAmount_ The amount of unit to sell
    /// @param route_ The route to use
    /// @param swapConnectorName_ The name of the swap connector
    /// @param swapCallData_ The call data to use
    function swapWstETHToWeETH(
        uint256 wstEthSellAmount_,
        uint256 unitAmount_,
        uint256 route_,
        string memory swapConnectorName_,
        bytes memory swapCallData_
    ) external nonReentrant onlyRebalancer {
        uint256 eEthPerWeETH_ = WEETH_CONTRACT.getEETHByWeETH(1e18);
        uint256 stEthPerWsteth_ = WSTETH_CONTRACT.stEthPerToken();

        (, ,uint256 assetsInEETHBefore_ , uint256 assetsInStEthBefore_, , ) = getRatioAaveV3(
            eEthPerWeETH_,
            stEthPerWsteth_
        );

        string[] memory targets_ = new string[](4);
        bytes[] memory calldatas_ = new bytes[](4);

        if (
            keccak256(abi.encodePacked(swapConnectorName_)) ==
            keccak256(abi.encodePacked("KYBER-AGGREGATOR-A")) ||
            keccak256(abi.encodePacked(swapConnectorName_)) ==
            keccak256(abi.encodePacked("PARASWAP-V6-A"))
        ) {
            targets_[0] = swapConnectorName_;
            calldatas_[0] = abi.encodeWithSignature(
                "swap(address,address,uint256,uint256,bytes,uint256)",
                WEETH_ADDRESS,
                WSTETH_ADDRESS,
                wstEthSellAmount_,
                unitAmount_,
                swapCallData_,
                9837247
            );
        } else if (
            keccak256(abi.encodePacked(swapConnectorName_)) ==
            keccak256(abi.encodePacked("1INCH-V6-A"))
        ) {
            targets_[0] = "1INCH-V6-A";
            calldatas_[0] = abi.encodeWithSignature(
                "sell(address,address,uint256,uint256,bytes,uint256)",
                WEETH_ADDRESS,
                WSTETH_ADDRESS,
                wstEthSellAmount_,
                unitAmount_,
                swapCallData_,
                9837247
            );
        } else {
            revert AaveV3WstETHWeETHSwapModule__InvalidSwapConnector();
        }

        targets_[1] = "AAVE-V3-A";
        calldatas_[1] = abi.encodeWithSignature(
            "deposit(address,uint256,uint256,uint256)",
            WEETH_ADDRESS,
            0,
            9837247,
            0
        );

        targets_[2] = "AAVE-V3-A";
        calldatas_[2] = abi.encodeWithSignature(
            "withdraw(address,uint256,uint256,uint256)",
            WSTETH_ADDRESS,
            wstEthSellAmount_,
            0,
            0
        );

        targets_[3] = "INSTAPOOL-D";
        calldatas_[3] = abi.encodeWithSignature(
            "flashPayback(address,uint256,uint256,uint256)",
            WSTETH_ADDRESS,
            wstEthSellAmount_,
            0,
            0
        );

        _wrapFlashloanSpellsAndCast(WSTETH_ADDRESS, wstEthSellAmount_, route_, targets_, calldatas_);

        (, , uint256 assetsInEETHAfter_, uint256 assetsInStEthAfter_, , ) = getRatioAaveV3(
            eEthPerWeETH_,
            stEthPerWsteth_
        );

        if ((assetsInEETHAfter_ + assetsInStEthAfter_) < (assetsInEETHBefore_ + assetsInStEthBefore_)) {
            revert AaveV3WstETHWeETHSwapModule__SwapNotProfitable();
        }

        revenue += (assetsInEETHAfter_ + assetsInStEthAfter_) - (assetsInEETHBefore_ + assetsInStEthBefore_);

        emit LogSwapWstETHToWeETH(
            wstEthSellAmount_,
            route_,
            (assetsInEETHAfter_ + assetsInStEthAfter_) - (assetsInEETHBefore_ + assetsInStEthBefore_),
            swapConnectorName_
        );
    }

    /// @notice Swaps weETH to wstETH
    /// @notice Assumes the position is weETH/ETH
    /// @param weEthSellAmount_ The amount of weETH to sell
    /// @param unitAmount_ The amount of unit to sell
    /// @param route_ The route to use
    /// @param swapConnectorName_ The name of the swap connector
    /// @param swapCallData_ The call data to use
    function swapWeETHToWstETH(
        uint256 weEthSellAmount_,
        uint256 unitAmount_,
        uint256 route_,
        string memory swapConnectorName_,
        bytes memory swapCallData_
    ) external nonReentrant onlyRebalancer {
        uint256 eEthPerWeETH_ = WEETH_CONTRACT.getEETHByWeETH(1e18);
        uint256 stEthPerWsteth_ = WSTETH_CONTRACT.stEthPerToken();

        (, , uint256 assetsInEETHBefore_, uint256 assetsInStEthBefore_, , ) = getRatioAaveV3(
            eEthPerWeETH_,
            stEthPerWsteth_
        );

        string[] memory targets_ = new string[](4);
        bytes[] memory calldatas_ = new bytes[](4);

        if (
            keccak256(abi.encodePacked(swapConnectorName_)) ==
            keccak256(abi.encodePacked("KYBER-AGGREGATOR-A")) ||
            keccak256(abi.encodePacked(swapConnectorName_)) ==
            keccak256(abi.encodePacked("PARASWAP-V6-A"))
        ) {
            targets_[0] = swapConnectorName_;
            calldatas_[0] = abi.encodeWithSignature(
                "swap(address,address,uint256,uint256,bytes,uint256)",
                WSTETH_ADDRESS,
                WEETH_ADDRESS,
                weEthSellAmount_,
                unitAmount_,
                swapCallData_,
                9837247
            );
        } else if (
            keccak256(abi.encodePacked(swapConnectorName_)) ==
            keccak256(abi.encodePacked("1INCH-V6-A"))
        ) {
            targets_[0] = "1INCH-V6-A";
            calldatas_[0] = abi.encodeWithSignature(
                "sell(address,address,uint256,uint256,bytes,uint256)",
                WSTETH_ADDRESS,
                WEETH_ADDRESS,
                weEthSellAmount_,
                unitAmount_,
                swapCallData_,
                9837247
            );
        } else {
            revert AaveV3WstETHWeETHSwapModule__InvalidSwapConnector();
        }

        targets_[1] = "AAVE-V3-A";
        calldatas_[1] = abi.encodeWithSignature(
            "deposit(address,uint256,uint256,uint256)",
            WSTETH_ADDRESS,
            0,
            9837247,
            0
        );

        targets_[2] = "AAVE-V3-A";
        calldatas_[2] = abi.encodeWithSignature(
            "withdraw(address,uint256,uint256,uint256)",
            WEETH_ADDRESS,
            weEthSellAmount_,
            0,
            0
        );

        targets_[3] = "INSTAPOOL-D";
        calldatas_[3] = abi.encodeWithSignature(
            "flashPayback(address,uint256,uint256,uint256)",
            WEETH_ADDRESS,
            weEthSellAmount_,
            0,
            0
        );

        _wrapFlashloanSpellsAndCast(WEETH_ADDRESS, weEthSellAmount_, route_, targets_, calldatas_);

        (, , uint256 assetsInEETHAfter_, uint256 assetsInStEthAfter_, , ) = getRatioAaveV3(
            eEthPerWeETH_,
            stEthPerWsteth_
        );

        if ((assetsInEETHAfter_ + assetsInStEthAfter_) < (assetsInEETHBefore_ + assetsInStEthBefore_)) {
            revert AaveV3WstETHWeETHSwapModule__SwapNotProfitable();
        }

        revenue += (assetsInEETHAfter_ + assetsInStEthAfter_) - (assetsInEETHBefore_ + assetsInStEthBefore_);

        emit LogSwapWeETHToWstETH(
            weEthSellAmount_,
            route_,
            (assetsInEETHAfter_ + assetsInStEthAfter_) - (assetsInEETHBefore_ + assetsInStEthBefore_),
            swapConnectorName_
        );
    }

    function _wrapFlashloanSpellsAndCast(
        address flashloanToken_,
        uint256 flashloanAmount_,
        uint256 route_,
        string[] memory targets_,
        bytes[] memory calldatas_
    ) internal {
        bytes memory encodedFlashData_ = abi.encode(targets_, calldatas_);

        // Execute the batch call to the flashloan target
        string[] memory flashTarget = new string[](1);
        bytes[] memory flashCalldata = new bytes[](1);

        flashTarget[0] = "INSTAPOOL-D";
        flashCalldata[0] = abi.encodeWithSignature(
            "flashBorrowAndCast(address,uint256,uint256,bytes,bytes)",
            flashloanToken_,
            flashloanAmount_,
            route_,
            encodedFlashData_,
            "0x"
        );

        vaultDSA.cast(flashTarget, flashCalldata, address(this));
    }
}
