    "contracts/vault/modules/refinanceModule/main.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity 0.8.17;

import "../../common/variablesBufferHelper.sol";
import "./events.sol";
import {IVault} from "../common/interface.sol";

contract RefinanceModule is VariablesBufferHelper, Events {
    /***********************************|
    |              ERRORS               |
    |__________________________________*/
    error RefinanceModule__Unsafe();

    /***********************************|
    |           REFINANCE CORE          |
    |__________________________________*/
    struct RefinanceVariables {
        // bool isFromStETHBasedProtocol;
        // bool isToStETHBasedProtocol;
        uint256 spellIndex;
        uint256 spellsLength;
        string[] targets;
        bytes[] calldatas;
        uint256 withdrawIdToPaybackFlashloan;
    }

    /// @notice Core function to perform refinance.
    /// @dev Note Flashloan will always be taken in `WSTETH`.
    /// @param fromProtocolId_ Id of the protocol to refinance from.
    /// @param toProtocolId_ Id of the protocol to refinance to.
    /// @param route_ Route for flashloan.
    /// @param wstETHflashAmount_ Amount of flashloan.
    /// @param wETHBorrowAmount_ Amount of wETH to be borrowed.
    /// @param withdrawAmount_ Amount to be withdrawn. Will always be in stETH.
    function refinance(
        uint8 fromProtocolId_,
        uint8 toProtocolId_,
        uint256 route_,
        uint256 wstETHflashAmount_,
        uint256 wETHBorrowAmount_,
        uint256 withdrawAmount_
    )
        external
        nonReentrant
        onlyRebalancer
        returns (uint256 ratioFromProtocol_, uint256 ratioToProtocol_)
    {
        if (
            fromProtocolId_ == 1 || // Aave v2
            toProtocolId_ == 1 || // Aave v2
            fromProtocolId_ == 4 || // Euler
            toProtocolId_ == 4 || // Euler
            fromProtocolId_ == 5 || // Morpho Aave v2
            toProtocolId_ == 5 || // Morpho Aave v2
            fromProtocolId_ == 6 || // Morpho Aave v3
            toProtocolId_ == 6 || // Morpho Aave v3
            fromProtocolId_ == 8 || // Fluid
            toProtocolId_ == 8 || // Fluid
            fromProtocolId_ == 11 || // Fluid Dex
            toProtocolId_ == 11 || // Fluid Dex
            fromProtocolId_ == 12 || // Fluid WeETH WstETH
            toProtocolId_ == 12 // Fluid WeETH WstETH
        ) {
            revert Helpers__ProtocolDisabled();
        }

        RefinanceVariables memory ref_;

        // /// @dev `wstETHflashAmount_` does not include withdraw and deposit spells.
        // /// They are considered in `withdrawAmount_` count.

        // to: deposit wstETH protocol -> 1
        // to: withdraw wstETH protocol, flashPayback wstETH -> 2
        if (wstETHflashAmount_ > 0) ref_.spellsLength += 3;

        // to: borrow wETH, from: payback wETH -> 2
        if (wETHBorrowAmount_ > 0) ref_.spellsLength += 2;

        // from: withdraw wstETH protocol, to: deposit wstETH protocol -> 2
        if (withdrawAmount_ > 0) ref_.spellsLength += 2;

        if (wETHBorrowAmount_ > 0) {
            if (fromProtocolId_ == 9 || toProtocolId_ == 9) {
                // If fluid New is toProtocolId_; spell to convert borrowed ETH to WETH
                // If fluid New is fromProtocolId_; spell to convert payback WETH to ETH
                ref_.spellsLength += 1;
            }
        }

        // withdrawAmount_ will always be in stETH.
        // Getting wstETH values for protocols supporting wstETH.
        uint256 fromWithdrawAmount_ = WSTETH_CONTRACT.getWstETHByStETH(withdrawAmount_);

        // To get the amount of stETH deposited from wstETH flashloan.
        uint256 flashDepositAmount_ = wstETHflashAmount_;

        ref_.targets = new string[](ref_.spellsLength);
        ref_.calldatas = new bytes[](ref_.spellsLength);

        // stETH => wstETH after withdraw for flashloan payback
        ref_.withdrawIdToPaybackFlashloan = 5236237;

        /**************************************|
        |   TAKE WSTETH FLASHLOAN AND DEPOSIT  |
        |_____________________________________*/

        if (wstETHflashAmount_ > 0) {
            if (toProtocolId_ == 2) {
                // to: wstETH based protocol
                ref_.targets[ref_.spellIndex] = "AAVE-V3-A";
                ref_.calldatas[ref_.spellIndex] = abi.encodeWithSignature(
                    "deposit(address,uint256,uint256,uint256)",
                    WSTETH_ADDRESS,
                    type(uint256).max,
                    0,
                    0
                );
            } else if (toProtocolId_ == 3) {
                // to: wstETH based protocol
                ref_.targets[ref_.spellIndex] = "COMPOUND-V3-A";
                ref_.calldatas[ref_.spellIndex] = abi.encodeWithSignature(
                    "deposit(address,address,uint256,uint256,uint256)",
                    COMP_ETH_MARKET_ADDRESS,
                    WSTETH_ADDRESS,
                    type(uint256).max,
                    0,
                    0
                );
            } else if (toProtocolId_ == 7) {
                // to: wstETH based protocol
                ref_.targets[ref_.spellIndex] = "SPARK-A";
                ref_.calldatas[ref_.spellIndex] = abi.encodeWithSignature(
                    "deposit(address,uint256,uint256,uint256)",
                    WSTETH_ADDRESS,
                    type(uint256).max,
                    0,
                    0
                );
            } else if (toProtocolId_ == 9) {
                // to: wstETH based protocol
                ref_.targets[ref_.spellIndex] = "FLUID-A";
                ref_.calldatas[ref_.spellIndex] = abi.encodeWithSignature(
                    "operate(address,uint256,int256,int256,uint256)",
                    FLUID_VAULT_ADDRESS_NEW,
                    FLUID_NFT_ID_NEW,
                    type(int256).max,
                    0,
                    0
                );
            } else if (toProtocolId_ == 10) {
                // to: wstETH based protocol
                ref_.targets[ref_.spellIndex] = "AAVE-V3-LIDO-A";
                ref_.calldatas[ref_.spellIndex] = abi.encodeWithSignature(
                    "deposit(address,uint256,uint256,uint256)",
                    WSTETH_ADDRESS,
                    type(uint256).max,
                    0,
                    0
                );
            } else {
                revert Helpers__UnsupportedProtocolId();
            }

            ref_.spellIndex++;
        }

        /***********************************|
        |      BORROW WETH AND PAYBACK       |
        |__________________________________*/

        if (wETHBorrowAmount_ > 0) {
            if (toProtocolId_ == 2) {
                // to: wstETH based protocol
                ref_.targets[ref_.spellIndex] = "AAVE-V3-A";
                ref_.calldatas[ref_.spellIndex] = abi.encodeWithSignature(
                    "borrow(address,uint256,uint256,uint256,uint256)",
                    WETH_ADDRESS,
                    wETHBorrowAmount_,
                    2,
                    0,
                    0
                );
            } else if (toProtocolId_ == 3) {
                // to: wstETH based protocol
                ref_.targets[ref_.spellIndex] = "COMPOUND-V3-A";
                ref_.calldatas[ref_.spellIndex] = abi.encodeWithSignature(
                    "borrow(address,address,uint256,uint256,uint256)",
                    COMP_ETH_MARKET_ADDRESS,
                    WETH_ADDRESS,
                    wETHBorrowAmount_,
                    0,
                    0
                );
            } else if (toProtocolId_ == 7) {
                // to: wstETH based protocol
                ref_.targets[ref_.spellIndex] = "SPARK-A";
                ref_.calldatas[ref_.spellIndex] = abi.encodeWithSignature(
                    "borrow(address,uint256,uint256,uint256,uint256)",
                    WETH_ADDRESS,
                    wETHBorrowAmount_,
                    2,
                    0,
                    0
                );
            } else if (toProtocolId_ == 9) {
                // to: wstETH based protocol
                ref_.targets[ref_.spellIndex] = "FLUID-A";
                ref_.calldatas[ref_.spellIndex] = abi.encodeWithSignature(
                    "operate(address,uint256,int256,int256,uint256)",
                    FLUID_VAULT_ADDRESS_NEW,
                    FLUID_NFT_ID_NEW,
                    0,
                    int256(wETHBorrowAmount_),
                    0
                );

                ref_.spellIndex++;

                ref_.targets[ref_.spellIndex] = "WETH-A";
                ref_.calldatas[ref_.spellIndex] = abi.encodeWithSignature(
                    "deposit(uint256,uint256,uint256)",
                    wETHBorrowAmount_,
                    0,
                    0
                );
            } else if (toProtocolId_ == 10) {
                // to: wstETH based protocol
                ref_.targets[ref_.spellIndex] = "AAVE-V3-LIDO-A";
                ref_.calldatas[ref_.spellIndex] = abi.encodeWithSignature(
                    "borrow(address,uint256,uint256,uint256,uint256)",
                    WETH_ADDRESS,
                    wETHBorrowAmount_,
                    2,
                    0,
                    0
                );
            }

            ref_.spellIndex++;

            if (fromProtocolId_ == 2) {
                // from: wstETH based protocol
                ref_.targets[ref_.spellIndex] = "AAVE-V3-A";
                ref_.calldatas[ref_.spellIndex] = abi.encodeWithSignature(
                    "payback(address,uint256,uint256,uint256,uint256)",
                    WETH_ADDRESS,
                    wETHBorrowAmount_,
                    2,
                    0,
                    0
                );
            } else if (fromProtocolId_ == 3) {
                // from: wstETH based protocol
                ref_.targets[ref_.spellIndex] = "COMPOUND-V3-A";
                ref_.calldatas[ref_.spellIndex] = abi.encodeWithSignature(
                    "payback(address,address,uint256,uint256,uint256)",
                    COMP_ETH_MARKET_ADDRESS,
                    WETH_ADDRESS,
                    wETHBorrowAmount_,
                    0,
                    0
                );
            } else if (fromProtocolId_ == 7) {
                // from: wstETH based protocol
                ref_.targets[ref_.spellIndex] = "SPARK-A";
                ref_.calldatas[ref_.spellIndex] = abi.encodeWithSignature(
                    "payback(address,uint256,uint256,uint256,uint256)",
                    WETH_ADDRESS,
                    wETHBorrowAmount_,
                    2,
                    0,
                    0
                );
            } else if (fromProtocolId_ == 9) {
                // Convert borrowed WETH to ETH
                ref_.targets[ref_.spellIndex] = "WETH-A";
                ref_.calldatas[ref_.spellIndex] = abi.encodeWithSignature(
                    "withdraw(uint256,uint256,uint256)",
                    wETHBorrowAmount_,
                    0,
                    0
                );

                ref_.spellIndex++;

                // to: wstETH based protocol
                ref_.targets[ref_.spellIndex] = "FLUID-A";
                ref_.calldatas[ref_.spellIndex] = abi.encodeWithSignature(
                    "operate(address,uint256,int256,int256,uint256)",
                    FLUID_VAULT_ADDRESS_NEW,
                    FLUID_NFT_ID_NEW,
                    0,
                    -int256(wETHBorrowAmount_),
                    wETHBorrowAmount_
                );
            } else if (fromProtocolId_ == 10) {
                // from: wstETH based protocol
                ref_.targets[ref_.spellIndex] = "AAVE-V3-LIDO-A";
                ref_.calldatas[ref_.spellIndex] = abi.encodeWithSignature(
                    "payback(address,uint256,uint256,uint256,uint256)",
                    WETH_ADDRESS,
                    wETHBorrowAmount_,
                    2,
                    0,
                    0
                );
            } else {
                revert Helpers__UnsupportedProtocolId();
            } 

            ref_.spellIndex++;
        }

        /*************************************|
        |     WITHDRAW wstETH AND DEPOSIT     |
        |____________________________________*/

        if (withdrawAmount_ > 0) {
            // even in case of flashloan, this amount will be withdrawn

            if (fromProtocolId_ == 2) {
                // wstETH based protocol

                ref_.targets[ref_.spellIndex] = "AAVE-V3-A";
                ref_.calldatas[ref_.spellIndex] = abi.encodeWithSignature(
                    "withdraw(address,uint256,uint256,uint256)",
                    WSTETH_ADDRESS,
                    fromWithdrawAmount_, // stETH amount converted to wstETH.
                    0,
                    0
                );
            } else if (fromProtocolId_ == 3) {
                // wstETH based protocol
                ref_.targets[ref_.spellIndex] = "COMPOUND-V3-A";
                ref_.calldatas[ref_.spellIndex] = abi.encodeWithSignature(
                    "withdraw(address,address,uint256,uint256,uint256)",
                    COMP_ETH_MARKET_ADDRESS,
                    WSTETH_ADDRESS,
                    fromWithdrawAmount_, // stETH amount converted to wstETH.
                    0,
                    0
                );
            } else if (fromProtocolId_ == 7) {
                // wstETH based protocol

                ref_.targets[ref_.spellIndex] = "SPARK-A";
                ref_.calldatas[ref_.spellIndex] = abi.encodeWithSignature(
                    "withdraw(address,uint256,uint256,uint256)",
                    WSTETH_ADDRESS,
                    fromWithdrawAmount_, // stETH amount converted to wstETH.
                    0,
                    0
                );
            } else if (fromProtocolId_ == 9) {
                // to: wstETH based protocol
                ref_.targets[ref_.spellIndex] = "FLUID-A";
                ref_.calldatas[ref_.spellIndex] = abi.encodeWithSignature(
                    "operate(address,uint256,int256,int256,uint256)",
                    FLUID_VAULT_ADDRESS_NEW,
                    FLUID_NFT_ID_NEW,
                    (-int256(fromWithdrawAmount_)),
                    0,
                    0
                );
            } else if (fromProtocolId_ == 10) {
                // wstETH based protocol
                ref_.targets[ref_.spellIndex] = "AAVE-V3-LIDO-A";
                ref_.calldatas[ref_.spellIndex] = abi.encodeWithSignature(
                    "withdraw(address,uint256,uint256,uint256)",
                    WSTETH_ADDRESS,
                    fromWithdrawAmount_, // stETH amount converted to wstETH.
                    0,
                    0
                );
            }

            ref_.spellIndex++;

            if (toProtocolId_ == 2) {
                // to: wstETH based protocol
                ref_.targets[ref_.spellIndex] = "AAVE-V3-A";
                ref_.calldatas[ref_.spellIndex] = abi.encodeWithSignature(
                    "deposit(address,uint256,uint256,uint256)",
                    WSTETH_ADDRESS,
                    type(uint256).max, // Depositing all wstETH
                    0,
                    0
                );
            } else if (toProtocolId_ == 3) {
                // to: wstETH based protocol
                ref_.targets[ref_.spellIndex] = "COMPOUND-V3-A";
                ref_.calldatas[ref_.spellIndex] = abi.encodeWithSignature(
                    "deposit(address,address,uint256,uint256,uint256)",
                    COMP_ETH_MARKET_ADDRESS,
                    WSTETH_ADDRESS,
                    type(uint256).max, // Depositing all wstETH
                    0,
                    0
                );
            } else if (toProtocolId_ == 7) {
                // to: wstETH based protocol
                ref_.targets[ref_.spellIndex] = "SPARK-A";
                ref_.calldatas[ref_.spellIndex] = abi.encodeWithSignature(
                    "deposit(address,uint256,uint256,uint256)",
                    WSTETH_ADDRESS,
                    type(uint256).max,
                    0,
                    0
                );
            } else if (toProtocolId_ == 9) {
                // to: wstETH based protocol
                ref_.targets[ref_.spellIndex] = "FLUID-A";
                ref_.calldatas[ref_.spellIndex] = abi.encodeWithSignature(
                    "operate(address,uint256,int256,int256,uint256)",
                    FLUID_VAULT_ADDRESS_NEW,
                    FLUID_NFT_ID_NEW,
                    type(int256).max, // Depositing all wstETH
                    0,
                    0
                );
            } else if (toProtocolId_ == 10) {
                // to: wstETH based protocol
                ref_.targets[ref_.spellIndex] = "AAVE-V3-LIDO-A";
                ref_.calldatas[ref_.spellIndex] = abi.encodeWithSignature(
                    "deposit(address,uint256,uint256,uint256)",
                    WSTETH_ADDRESS,
                    type(uint256).max, // Depositing all wstETH
                    0,
                    0
                );
            } else {
                revert Helpers__UnsupportedProtocolId();
            } 

            ref_.spellIndex++;
        }

        /***************************************|
        |   WITHDRAW WSTETH AND FLASH PAYBACK   |
        |______________________________________*/

        if (wstETHflashAmount_ > 0) {
            if (toProtocolId_ == 2) {
                // wstETH based protocol

                ref_.targets[ref_.spellIndex] = "AAVE-V3-A";
                ref_.calldatas[ref_.spellIndex] = abi.encodeWithSignature(
                    "withdraw(address,uint256,uint256,uint256)",
                    WSTETH_ADDRESS,
                    flashDepositAmount_, // flash amount in wstETH
                    0,
                    0
                );
            } else if (toProtocolId_ == 3) {
                // wstETH based protocol

                ref_.targets[ref_.spellIndex] = "COMPOUND-V3-A";
                ref_.calldatas[ref_.spellIndex] = abi.encodeWithSignature(
                    "withdraw(address,address,uint256,uint256,uint256)",
                    COMP_ETH_MARKET_ADDRESS,
                    WSTETH_ADDRESS,
                    flashDepositAmount_, // flash amount in wstETH
                    0,
                    0
                );
            } else if (toProtocolId_ == 7) {
                // wstETH based protocol

                ref_.targets[ref_.spellIndex] = "SPARK-A";
                ref_.calldatas[ref_.spellIndex] = abi.encodeWithSignature(
                    "withdraw(address,uint256,uint256,uint256)",
                    WSTETH_ADDRESS,
                    flashDepositAmount_,
                    0,
                    0
                );
            } else if (toProtocolId_ == 9) {
                // to: wstETH based protocol
                ref_.targets[ref_.spellIndex] = "FLUID-A";
                ref_.calldatas[ref_.spellIndex] = abi.encodeWithSignature(
                    "operate(address,uint256,int256,int256,uint256)",
                    FLUID_VAULT_ADDRESS_NEW,
                    FLUID_NFT_ID_NEW,
                    -int256(flashDepositAmount_),
                    0,
                    0
                );
            } else if (toProtocolId_ == 10) {
                // wstETH based protocol
                ref_.targets[ref_.spellIndex] = "AAVE-V3-LIDO-A";
                ref_.calldatas[ref_.spellIndex] = abi.encodeWithSignature(
                    "withdraw(address,uint256,uint256,uint256)",
                    WSTETH_ADDRESS,
                    flashDepositAmount_, // flash amount in wstETH
                    0,
                    0
                );
            } else {
                revert Helpers__UnsupportedProtocolId();
            }

            ref_.spellIndex++;

            ref_.targets[ref_.spellIndex] = "INSTAPOOL-D";
            ref_.calldatas[ref_.spellIndex] = abi.encodeWithSignature(
                "flashPayback(address,uint256,uint256,uint256)",
                WSTETH_ADDRESS,
                wstETHflashAmount_,
                0,
                0
            );

            /*********************************|
            |    CAST SPELLS WITH FLASHLOAN   |
            |________________________________*/
            bytes memory encodedFlashData_ = abi.encode(
                ref_.targets,
                ref_.calldatas
            );

            string[] memory flashTarget = new string[](1);
            bytes[] memory flashCalldata = new bytes[](1);
            flashTarget[0] = "INSTAPOOL-D";
            flashCalldata[0] = abi.encodeWithSignature(
                "flashBorrowAndCast(address,uint256,uint256,bytes,bytes)",
                WSTETH_ADDRESS,
                wstETHflashAmount_,
                route_,
                encodedFlashData_,
                "0x"
            );

            vaultDSA.cast(flashTarget, flashCalldata, address(this));
        } else {
            /******************|
            |    CAST SPELLS   |
            |_________________*/

            vaultDSA.cast(ref_.targets, ref_.calldatas, address(this));
        }

        uint256 fromRatio_ = IVault(address(this)).getProtocolRatio(
            fromProtocolId_
        );
        uint256 toRatio_ = IVault(address(this)).getProtocolRatio(
            toProtocolId_
        );

        if (
            fromRatio_ < maxRiskRatio[fromProtocolId_] &&
            toRatio_ < maxRiskRatio[toProtocolId_]
        ) {
            emit LogRefinance(
                fromProtocolId_,
                toProtocolId_,
                route_,
                wstETHflashAmount_,
                wETHBorrowAmount_,
                withdrawAmount_
            );

            return (fromRatio_, toRatio_);
        } else {
            revert RefinanceModule__Unsafe();
        }
    }
}
