    "contracts/vault/modules/leverageModule/main.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity 0.8.17;

import "../../common/variablesBufferHelper.sol";
import "./events.sol";
import {IVault, TokenInterface} from "../common/interface.sol";

/// @title LeverageModule
/// @dev Actions are executable by allowed rebalancers only
contract LeverageModule is VariablesBufferHelper, Events {
    /***********************************|
    |              ERRORS               |
    |__________________________________*/
    // Revert if protocol or vault overall ratio after leverage is more than max.
    error LeverageModule__UnequalLength();
    error LeverageModule__UnitAmountLess();
    error LeverageModule__AggregatedRatioExceeded();
    error LeverageModule__MaxRiskRatioExceeded();
    error LeverageModule__LessAssetsReceived();

    struct LeverageMemoryVariables {
        uint256 spellIndex;
        uint256 spellsLength;
        uint256 vaultsLength;
        string[] targets;
        bytes[] calldatas;
        uint256 flashStETH;
        uint256 beforeNetAssets;
        uint256 afterNetAssets;
        uint256 aggregatedRatio;
        uint256 vaultSwapAmt; // Var to set the total amount of astETH Received from old vault deleverage. Used for swapping astETH to stETH.
        uint256 wstethPerWeth;
    }

    /// @notice Core function to perform leverage.
    /// @dev Note Flashloan will always be taken in `WSTETH`.
    /// @param protocolId_ Id of the protocol to leverage.
    /// @param route_ Route for flashloan
    /// @param wstETHflashAmount_ Amount of flashloan.
    /// @param wETHBorrowAmount_ Amount of weth to be borrowed.
    /// @param vaults_ Addresses of old vaults to deleverage.
    /// @param vaultAmounts_ Amount of `WETH` that we will payback in old vaults.
    /// @param swapMode_ Mode of swap.(0 = no swap, 1 = Swap Aggregator, 2 = direct Lido route)
    /// @param _swapConnectors Array of swap aggregator connectors to route swap from.
    /// @param _swapDatas Array of bytes calldata required for `WETH` to `WSTETH` swapping.
    /// @param unitAmount_ `WSTETH` per `WETH` conversion ratio with slippage.
    /// @dev Note `WETH` will always be swapped to `WSTETH`,
    /// even if the protocol accepts STETH. (This is done to add simplicity to the vault).
    function leverage(
        uint8 protocolId_,
        uint256 route_,
        uint256 wstETHflashAmount_,
        uint256 wETHBorrowAmount_,
        address[] memory vaults_,
        uint256[] memory vaultAmounts_,
        uint256 swapMode_,
        string[] memory _swapConnectors,
        bytes[] memory _swapDatas,
        uint256 unitAmount_
    ) external nonReentrant onlyRebalancer {
        if (
            protocolId_ == 1 || // Aave v2
            protocolId_ == 4 || // Euler
            protocolId_ == 5 || // Morpho Aave v2
            protocolId_ == 6 || // Morpho Aave v3
            protocolId_ == 8 || // Fluid
            protocolId_ == 11 || // Fluid Dex
            protocolId_ == 12 // Fluid WeETH WstETH
        ) {
            revert Helpers__ProtocolDisabled();
        }

        LeverageMemoryVariables memory lev_;
        lev_.vaultsLength = vaultAmounts_.length;
        if (!(vaults_.length == lev_.vaultsLength))
            revert LeverageModule__UnequalLength();

        // Includes eth borrow + stETH deposit
        lev_.spellsLength = 2;


        // wstETH based protocol

        // Includes flash deposit, withdraw, and flash payback.
        if (wstETHflashAmount_ > 0) lev_.spellsLength += 3;
        // Includes deleveraging other vaults, converting astETH into stETH, wrapping
        // stETH into wstETH (deleveraging other vaults gives astETH in return at 1:1)
        if (lev_.vaultsLength > 0) {
            lev_.spellsLength += lev_.vaultsLength + 2;
        }

        // Includes swap.
        if (swapMode_ == 1) {
            lev_.spellsLength += 1;
            // Includes direct Lido route. wETH => eth => stETH => wstETH.
        } else if (swapMode_ == 2) {
            lev_.spellsLength += 3;
        }

        if (protocolId_ == 9) {
            // Spell to convert borrowed ETH to WETH so it can be swapped to WSTETH.
            lev_.spellsLength += 1;
        }

        // Var to set the total amount of astETH Received from old vault deleverage.
        // Used for swapping astETH to stETH.

        lev_.targets = new string[](lev_.spellsLength);
        lev_.calldatas = new bytes[](lev_.spellsLength);

        (, , lev_.beforeNetAssets, , ) = IVault(address(this)).getNetAssets();

        /***********************************|
        |     FLASHLOAN wstETH DEPOSIT      |
        |__________________________________*/
        if (wstETHflashAmount_ > 0) {
            // Flashloan needed. Hence adding spells to deposit flashloan received.
            if (protocolId_ == 2) {
                lev_.targets[lev_.spellIndex] = "AAVE-V3-A";
                lev_.calldatas[lev_.spellIndex] = abi.encodeWithSignature(
                    "deposit(address,uint256,uint256,uint256)",
                    WSTETH_ADDRESS,
                    type(uint256).max,
                    0,
                    0
                );
            } else if (protocolId_ == 3) {
                lev_.targets[lev_.spellIndex] = "COMPOUND-V3-A";
                lev_.calldatas[lev_.spellIndex] = abi.encodeWithSignature(
                    "deposit(address,address,uint256,uint256,uint256)",
                    COMP_ETH_MARKET_ADDRESS,
                    WSTETH_ADDRESS,
                    type(uint256).max,
                    0,
                    0
                );
            } else if (protocolId_ == 7) {
                lev_.targets[lev_.spellIndex] = "SPARK-A";
                lev_.calldatas[lev_.spellIndex] = abi.encodeWithSignature(
                    "deposit(address,uint256,uint256,uint256)",
                    WSTETH_ADDRESS,
                    type(uint256).max,
                    0,
                    0
                );
            } else if (protocolId_ == 9) {
                lev_.targets[lev_.spellIndex] = "FLUID-A";
                lev_.calldatas[lev_.spellIndex] = abi.encodeWithSignature(
                    "operate(address,uint256,int256,int256,uint256)", // to deposit
                    FLUID_VAULT_ADDRESS_NEW,
                    FLUID_NFT_ID_NEW,
                    type(int256).max,
                    0,
                    0
                );
            } else if (protocolId_ == 10) {
                lev_.targets[lev_.spellIndex] = "AAVE-V3-LIDO-A";
                lev_.calldatas[lev_.spellIndex] = abi.encodeWithSignature(
                    "deposit(address,uint256,uint256,uint256)",
                    WSTETH_ADDRESS,
                    type(uint256).max,
                    0,
                    0
                );
            }

            lev_.spellIndex++;
        }

        /***********************************|
        |            WETH BORROW             |
        |__________________________________*/

        if (protocolId_ == 2) {
            lev_.targets[lev_.spellIndex] = "AAVE-V3-A";
            lev_.calldatas[lev_.spellIndex] = abi.encodeWithSignature(
                "borrow(address,uint256,uint256,uint256,uint256)",
                WETH_ADDRESS,
                wETHBorrowAmount_,
                2,
                0,
                0
            );
        } else if (protocolId_ == 3) {
            lev_.targets[lev_.spellIndex] = "COMPOUND-V3-A";
            lev_.calldatas[lev_.spellIndex] = abi.encodeWithSignature(
                "borrow(address,address,uint256,uint256,uint256)",
                COMP_ETH_MARKET_ADDRESS,
                WETH_ADDRESS,
                wETHBorrowAmount_,
                0,
                0
            );
        } else if (protocolId_ == 7) {
            lev_.targets[lev_.spellIndex] = "SPARK-A";
            lev_.calldatas[lev_.spellIndex] = abi.encodeWithSignature(
                "borrow(address,uint256,uint256,uint256,uint256)",
                WETH_ADDRESS,
                wETHBorrowAmount_,
                2,
                0,
                0
            );
        } else if (protocolId_ == 9) {
            lev_.targets[lev_.spellIndex] = "FLUID-A";
            lev_.calldatas[lev_.spellIndex] = abi.encodeWithSignature(
                "operate(address,uint256,int256,int256,uint256)",
                FLUID_VAULT_ADDRESS_NEW,
                FLUID_NFT_ID_NEW,
                0,
                int256(wETHBorrowAmount_),
                0
            );

            lev_.spellIndex++;

            lev_.targets[lev_.spellIndex] = "WETH-A";
            lev_.calldatas[lev_.spellIndex] = abi.encodeWithSignature(
                "deposit(uint256,uint256,uint256)",
                wETHBorrowAmount_,
                0,
                0
            );
        } else if (protocolId_ == 10) {
            lev_.targets[lev_.spellIndex] = "AAVE-V3-LIDO-A";
            lev_.calldatas[lev_.spellIndex] = abi.encodeWithSignature(
                "borrow(address,uint256,uint256,uint256,uint256)",
                WETH_ADDRESS,
                wETHBorrowAmount_,
                2,
                0,
                0
            );
        }

        lev_.spellIndex++;

        /***********************************|
        |       DELEVERAGE V1 VAULTS        |
        |__________________________________*/

        if (lev_.vaultsLength > 0) {
            for (uint256 k = 0; k < lev_.vaultsLength; k++) {
                lev_.targets[lev_.spellIndex] = "LITE-A"; // Instadapp Lite v1 vaults connector
                lev_.calldatas[lev_.spellIndex] = abi.encodeWithSignature(
                    "deleverage(address,uint256,uint256,uint256)",
                    vaults_[k],
                    vaultAmounts_[k],
                    0,
                    0
                );

                lev_.spellIndex++;

                // We'll receive astETH 1:1 for wETH payback.
                wETHBorrowAmount_ -= vaultAmounts_[k];
                lev_.vaultSwapAmt += vaultAmounts_[k];
            }

            lev_.targets[lev_.spellIndex] = "AAVE-V2-A";
            lev_.calldatas[lev_.spellIndex] = abi.encodeWithSignature(
                "withdraw(address,uint256,uint256,uint256)",
                STETH_ADDRESS,
                lev_.vaultSwapAmt, // Not taking buffer since we will mostly have borrowed assets on aave so buffer case will be covered.
                0,
                0
            );

            lev_.spellIndex++;

            // wstETH based protocols
            lev_.targets[lev_.spellIndex] = "WSTETH-A";
            lev_.calldatas[lev_.spellIndex] = abi.encodeWithSignature(
                "deposit(uint256,uint256,uint256)",
                type(uint256).max, // Swap all the stETH amount Received through Aave.
                0,
                0
            );

            lev_.spellIndex++;
        }

        /**************************|
        |    WETH => WSTETH SWAP   |
        |_________________________*/

        if (swapMode_ > 0) {
            if (swapMode_ == 1) {
                // swap via swap aggregator
                // wstethPerWeth will always be < 1, considering wETH is 1:1 with stETH.
                lev_.wstethPerWeth = WSTETH_CONTRACT.tokensPerStEth();
                if (unitAmount_ < (lev_.wstethPerWeth - leverageMaxUnitAmountLimit))
                    revert LeverageModule__UnitAmountLess();

                lev_.targets[lev_.spellIndex] = "SWAP-AGGREGATOR-A";
                lev_.calldatas[lev_.spellIndex] = abi.encodeWithSignature(
                    "swap(string[],bytes[])",
                    _swapConnectors,
                    _swapDatas
                );
                lev_.spellIndex++;
            }

            // Unwrapping wstETH to stETH after swap(wETH => wstETH)
            if (swapMode_ == 2) {
                // convert wETH into ETH
                lev_.targets[lev_.spellIndex] = "WETH-A";
                lev_.calldatas[lev_.spellIndex] = abi.encodeWithSignature(
                    "withdraw(uint256,uint256,uint256)",
                    wETHBorrowAmount_,
                    0,
                    0
                );
                lev_.spellIndex++;

                // convert ETH into stETH
                lev_.targets[lev_.spellIndex] = "LIDO-STETH-A";
                lev_.calldatas[lev_.spellIndex] = abi.encodeWithSignature(
                    "deposit(uint256,uint256,uint256)",
                    wETHBorrowAmount_,
                    0,
                    0
                );
                lev_.spellIndex++;

                // wrapping stETH to wstETH
                // wstETH based protocols
                lev_.targets[lev_.spellIndex] = "WSTETH-A";
                lev_.calldatas[lev_.spellIndex] = abi.encodeWithSignature(
                    "deposit(uint256,uint256,uint256)",
                    type(uint256).max,
                    0,
                    0
                );
                lev_.spellIndex++;
            }
        }

        /***********************************|
        |         COLLATERAL DEPOSIT        |
        |__________________________________*/

        /// If protocol is 1 or 5, DSA would currently have all stETH (since we unwrapped all wstETH from swap).
        /// If protocol is wstETH based, DSA would currently have all wstETH (since we have wrapped all the stETH to wstETH).
        if (protocolId_ == 2) {
            // wstETH based protocol
            lev_.targets[lev_.spellIndex] = "AAVE-V3-A";
            lev_.calldatas[lev_.spellIndex] = abi.encodeWithSignature(
                "deposit(address,uint256,uint256,uint256)",
                WSTETH_ADDRESS,
                type(uint256).max,
                0,
                0
            );
        } else if (protocolId_ == 3) {
            // wstETH based protocol
            lev_.targets[lev_.spellIndex] = "COMPOUND-V3-A";
            lev_.calldatas[lev_.spellIndex] = abi.encodeWithSignature(
                "deposit(address,address,uint256,uint256,uint256)",
                COMP_ETH_MARKET_ADDRESS,
                WSTETH_ADDRESS,
                type(uint256).max,
                0,
                0
            );
        } else if (protocolId_ == 7) {
            // wstETH based protocol
            lev_.targets[lev_.spellIndex] = "SPARK-A";
            lev_.calldatas[lev_.spellIndex] = abi.encodeWithSignature(
                "deposit(address,uint256,uint256,uint256)",
                WSTETH_ADDRESS,
                type(uint256).max,
                0,
                0
            );
        } else if (protocolId_ == 9) {
            lev_.targets[lev_.spellIndex] = "FLUID-A";
            lev_.calldatas[lev_.spellIndex] = abi.encodeWithSignature(
                "operate(address,uint256,int256,int256,uint256)",
                FLUID_VAULT_ADDRESS_NEW,
                FLUID_NFT_ID_NEW,
                type(int256).max,
                0,
                0
            );
        } else if (protocolId_ == 10) {
            // wstETH based protocol
            lev_.targets[lev_.spellIndex] = "AAVE-V3-LIDO-A";
            lev_.calldatas[lev_.spellIndex] = abi.encodeWithSignature(
                "deposit(address,uint256,uint256,uint256)",
                WSTETH_ADDRESS,
                type(uint256).max,
                0,
                0
            );
        }
        lev_.spellIndex++;

        /***********************************|
        |         WITHDRAW FLASHLOAN        |
        |__________________________________*/

        if (wstETHflashAmount_ > 0) {
            if (protocolId_ == 2) {
                lev_.targets[lev_.spellIndex] = "AAVE-V3-A";
                lev_.calldatas[lev_.spellIndex] = abi.encodeWithSignature(
                    "withdraw(address,uint256,uint256,uint256)",
                    WSTETH_ADDRESS,
                    wstETHflashAmount_,
                    0,
                    0
                );
            } else if (protocolId_ == 3) {
                lev_.targets[lev_.spellIndex] = "COMPOUND-V3-A";
                lev_.calldatas[lev_.spellIndex] = abi.encodeWithSignature(
                    "withdraw(address,address,uint256,uint256,uint256)",
                    COMP_ETH_MARKET_ADDRESS,
                    WSTETH_ADDRESS,
                    wstETHflashAmount_,
                    0,
                    0
                );
            } else if (protocolId_ == 7) {
                lev_.targets[lev_.spellIndex] = "SPARK-A";
                lev_.calldatas[lev_.spellIndex] = abi.encodeWithSignature(
                    "withdraw(address,uint256,uint256,uint256)",
                    WSTETH_ADDRESS,
                    wstETHflashAmount_,
                    0,
                    0
                );
            } else if (protocolId_ == 9) {
                lev_.targets[lev_.spellIndex] = "FLUID-A";
                lev_.calldatas[lev_.spellIndex] = abi.encodeWithSignature(
                    "operate(address,uint256,int256,int256,uint256)",
                    FLUID_VAULT_ADDRESS_NEW,
                    FLUID_NFT_ID_NEW,
                    -int256(wstETHflashAmount_), // withdraw
                    0,
                    0
                );
            } else if (protocolId_ == 10) {
                lev_.targets[lev_.spellIndex] = "AAVE-V3-LIDO-A";
                lev_.calldatas[lev_.spellIndex] = abi.encodeWithSignature(
                    "withdraw(address,uint256,uint256,uint256)",
                    WSTETH_ADDRESS,
                    wstETHflashAmount_,
                    0,
                    0
                );
            }
            lev_.spellIndex++;

            lev_.targets[lev_.spellIndex] = "INSTAPOOL-D";
            lev_.calldatas[lev_.spellIndex] = abi.encodeWithSignature(
                "flashPayback(address,uint256,uint256,uint256)",
                WSTETH_ADDRESS,
                wstETHflashAmount_,
                0,
                0
            );
            lev_.spellIndex++;

            bytes memory encodedFlashData_ = abi.encode(
                lev_.targets,
                lev_.calldatas
            );

            string[] memory flashTarget = new string[](1);
            bytes[] memory flashCalldata = new bytes[](1);
            flashTarget[0] = "INSTAPOOL-D";
            flashCalldata[0] = abi.encodeWithSignature(
                "flashBorrowAndCast(address,uint256,uint256,bytes,bytes)",
                WSTETH_ADDRESS,
                wstETHflashAmount_,
                route_,
                encodedFlashData_,
                "0x"
            );

            vaultDSA.cast(flashTarget, flashCalldata, address(this));
        } else {
            vaultDSA.cast(lev_.targets, lev_.calldatas, address(this));
        }

        // Verifying that the max risk ratio of the vault is less than the max ratio allowed.
        if (IVault(address(this)).getProtocolRatio(protocolId_) > maxRiskRatio[protocolId_]) {
            revert LeverageModule__MaxRiskRatioExceeded();
        }

        // Verifying that the aggregated ratio of the vault is less than the max ratio allowed.
        (, , lev_.afterNetAssets, lev_.aggregatedRatio, ) = IVault(address(this)).getNetAssets();

        if (lev_.afterNetAssets > lev_.beforeNetAssets) {
            revenue = revenue + lev_.afterNetAssets - lev_.beforeNetAssets;
        } else if ((((lev_.beforeNetAssets * (1e8 - 1)) / 1e8) > lev_.afterNetAssets)) {
            revert LeverageModule__LessAssetsReceived();
        }

        if (lev_.aggregatedRatio > aggrMaxVaultRatio) {
            revert LeverageModule__AggregatedRatioExceeded();
        }

        emit LogLeverage(
            protocolId_,
            route_,
            wstETHflashAmount_,
            wETHBorrowAmount_,
            vaults_,
            vaultAmounts_,
            swapMode_,
            unitAmount_,
            lev_.vaultSwapAmt
        );
    }
}
"
