import '@openzeppelin/contracts/interfaces/IERC4626.sol';
import '@openzeppelin/contracts/token/ERC20/IERC20.sol';
import '@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol';

import '../ZunamiStratBase.sol';

abstract contract ERC4626StratBase is ZunamiStratBase {
    using SafeERC20 for IERC20;

    IERC4626 public immutable vault;
    IERC20 public immutable vaultAsset;

    uint256 public depositedAssets;

    uint256 internal constant SHARES = 1e18;

    constructor(
        IERC20[POOL_ASSETS] memory tokens_,
        uint256[POOL_ASSETS] memory tokenDecimalsMultipliers_,
        address vaultAddr,
        address vaultAssetAddr
    ) ZunamiStratBase(tokens_, tokenDecimalsMultipliers_) {
        if (address(vaultAddr) == address(0)) revert ZeroAddress();
        if (address(vaultAssetAddr) == address(0)) revert ZeroAddress();
        vault = IERC4626(vaultAddr);
        vaultAsset = IERC20(vaultAssetAddr);
    }

    function getLiquidityTokenPrice() internal view virtual override returns (uint256) {
        return (oracle.getUSDPrice(address(vaultAsset)) * vault.convertToAssets(SHARES)) / SHARES;
    }

    function convertVaultAssetAmounts(
        uint256[POOL_ASSETS] memory amounts
    ) internal view virtual returns (uint256 amount);

    function depositLiquidity(
        uint256[POOL_ASSETS] memory amounts
    ) internal virtual override returns (uint256) {
        uint256 amount = convertAndApproveTokens(address(vault), amounts);
        depositedAssets += amount;

        return vault.deposit(amount, address(this));
    }

    function convertAndApproveTokens(
        address vault,
        uint256[POOL_ASSETS] memory amounts
    ) internal virtual returns (uint256 amount);

    function calcTokenAmount(
        uint256[POOL_ASSETS] memory tokenAmounts,
        bool
    ) public view override returns (uint256 sharesAmount) {
        return vault.convertToShares(convertVaultAssetAmounts(tokenAmounts));
    }

    function removeLiquidity(
        uint256 amount,
        uint256[POOL_ASSETS] memory,
        bool
    ) internal virtual override {
        uint256 assets = vault.redeem(amount, address(this), address(this));
        if(depositedAssets > assets) {
            depositedAssets -= assets;
        } else {
            depositedAssets = 0;
        }
    }

    function claimCollectedRewards() internal virtual override {
        uint256 redeemableAssets = vault.previewRedeem(depositedLiquidity);
        if (redeemableAssets > depositedAssets) {
            uint256 withdrawnAssets = redeemableAssets - depositedAssets;
            uint256 withdrawnShares = vault.convertToShares(withdrawnAssets);
            uint256[POOL_ASSETS] memory minTokenAmounts;
            removeLiquidity(withdrawnShares, minTokenAmounts, false);
            depositedLiquidity -= withdrawnShares;
        }
    }
}
"
    },
    "contracts/strategies/erc4626/stakeDao/llamalend/CrvUsdStakeDaoERC4626StratBase.sol": {
      "content": "//SPDX-License-Identifier: MIT
pragma solidity ^0.8.23;

import '../../../../utils/Constants.sol';
import '../../../../interfaces/ITokenConverter.sol';
import '../StakeDaoERC4626StratBase.sol';

contract CrvUsdStakeDaoERC4626StratBase is StakeDaoERC4626StratBase {
    using SafeERC20 for IERC20;

    uint256 public constant ZUNAMI_DAI_TOKEN_ID = 0;
    uint256 public constant ZUNAMI_USDC_TOKEN_ID = 1;
    uint256 public constant ZUNAMI_USDT_TOKEN_ID = 2;

    IERC20 public constant CRVUSD = IERC20(Constants.CRVUSD_ADDRESS);

    ITokenConverter public converter;

    event SetTokenConverter(address converter);

    constructor(
        IERC20[POOL_ASSETS] memory _tokens,
        uint256[POOL_ASSETS] memory _tokenDecimalsMultipliers,
        address _vault4626Addr,
        address _vaultAssetAddr,
        address _vaultSdAddr
    )
        StakeDaoERC4626StratBase(
            _tokens,
            _tokenDecimalsMultipliers,
            _vault4626Addr,
            _vaultAssetAddr,
            _vaultSdAddr
        )
    {}

    function setTokenConverter(address converterAddr) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (address(converterAddr) == address(0)) revert ZeroAddress();
        converter = ITokenConverter(converterAddr);
        emit SetTokenConverter(converterAddr);
    }

    function convertVaultAssetAmounts(
        uint256[POOL_ASSETS] memory amounts
    ) internal view override returns (uint256 amount) {
        return
            converter.valuate(
                Constants.DAI_ADDRESS,
                Constants.CRVUSD_ADDRESS,
                amounts[ZUNAMI_DAI_TOKEN_ID]
            ) +
            converter.valuate(
                Constants.USDC_ADDRESS,
                Constants.CRVUSD_ADDRESS,
                amounts[ZUNAMI_USDC_TOKEN_ID]
            ) +
            converter.valuate(
                Constants.USDT_ADDRESS,
                Constants.CRVUSD_ADDRESS,
                amounts[ZUNAMI_USDT_TOKEN_ID]
            );
    }

    function convertAndApproveTokens(
        address vault,
        uint256[POOL_ASSETS] memory amounts
    ) internal override returns (uint256 amount) {
        for (uint256 i = 0; i < POOL_ASSETS; ++i) {
            if (amounts[i] > 0) {
                tokens[i].safeTransfer(address(converter), amounts[i]);
                converter.handle(
                    address(tokens[i]),
                    Constants.CRVUSD_ADDRESS,
                    amounts[i],
                    applySlippageDifferentPrice(
                        amounts[i],
                        address(tokens[i]),
                        Constants.CRVUSD_ADDRESS
                    ) * tokenDecimalsMultipliers[i]
                );
            }
        }
        amount = CRVUSD.balanceOf(address(this));
        CRVUSD.safeIncreaseAllowance(address(vault), amount);
    }

    function removeLiquidity(
        uint256 amount,
        uint256[POOL_ASSETS] memory minAmounts,
        bool isHarvest
    ) internal override {
        super.removeLiquidity(amount, minAmounts, isHarvest);

        uint256 crvUSDBalance = CRVUSD.balanceOf(address(this));
        CRVUSD.safeTransfer(address(converter), crvUSDBalance);
        converter.handle(
            Constants.CRVUSD_ADDRESS,
            Constants.USDT_ADDRESS,
            crvUSDBalance,
            applySlippageDifferentPrice(
                crvUSDBalance,
                Constants.CRVUSD_ADDRESS,
                Constants.USDT_ADDRESS
            ) / tokenDecimalsMultipliers[ZUNAMI_USDT_TOKEN_ID]
        );
    }
}
"
