    "contracts/libs/ERC721A.sol": {
      "content": "// SPDX-License-Identifier: MIT
// ERC721A Contracts v4.2.3
// Creator: Chiru Labs
// Commit 1843596cf863557fcd3bf0105222a7c29690af5c

pragma solidity ^0.8.4;

import './IERC721A.sol';

/**
 * @dev Interface of ERC721 token receiver.
