    "src/libraries/ZenjiGovLib.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity ^0.8.33;

import { TimelockLib } from "./TimelockLib.sol";
import { IYieldStrategy } from "../interfaces/IYieldStrategy.sol";
import { ZenjiConstants } from "./ZenjiConstants.sol";

interface ISwapperSlippage {
    function setSlippage(uint256 newSlippage) external;
}

/// @title ZenjiGovLib
/// @notice Cold-path gov parameter administration extracted from Zenji to reduce vault bytecode.
/// @dev All functions are `public` and run via DELEGATECALL from the vault, so `address(this)` is
///      the vault: storage pointers operate on the vault's storage, events are emitted from the
///      vault address, and external calls (setSlippage) carry the vault as msg.sender. The vault
///      resolves its virtual `MAX_TARGET_LTV()` and the loan manager's `maxLtvBps()` and passes
///      them in as values, since a library cannot call the vault's virtuals.
library ZenjiGovLib {
    using TimelockLib for TimelockLib.TimelockData;

    // ---- bounds (I-01: single source = ZenjiConstants; aliased so the body reads unchanged) ----
    uint256 internal constant MAX_FEE_RATE = ZenjiConstants.MAX_FEE_RATE;
    uint256 internal constant MIN_TARGET_LTV = ZenjiConstants.MIN_TARGET_LTV;
    uint256 internal constant MAX_REBALANCE_BOUNTY = ZenjiConstants.MAX_REBALANCE_BOUNTY;
    uint256 internal constant MAX_VAULT_SLIPPAGE = ZenjiConstants.MAX_VAULT_SLIPPAGE;
    /// @dev Must match BaseYieldStrategy.MIN_SLIPPAGE — the vault rejects sub-floor values
    ///      up front rather than letting the strategy's setSlippage revert the whole param change.
    uint256 internal constant MIN_VAULT_SLIPPAGE = ZenjiConstants.MIN_VAULT_SLIPPAGE;
    uint256 internal constant PARAM_TIMELOCK_DELAY = ZenjiConstants.PARAM_TIMELOCK_DELAY;

    /// @notice Snapshot of the five gov-settable scalar params, threaded in and back out.
    struct ParamState {
        uint256 feeRate;
        uint256 targetLtv;
        uint256 depositCap;
        uint256 rebalanceBountyRate;
        uint256 maxSlippage;
    }

    // ---- events (same signatures as Zenji; topics match on emit via delegatecall) ----
    event ParamUpdated(uint8 indexed param, uint256 oldValue, uint256 newValue);
    event FeeRateChangeProposed(uint256 currentFeeRate, uint256 newFeeRate, uint256 effectiveTime);
    event TargetLtvChangeProposed(uint256 currentLtv, uint256 newLtv, uint256 effectiveTime);
    event BountyRateChangeProposed(uint256 currentRate, uint256 newRate, uint256 effectiveTime);
    event DepositCapChangeProposed(uint256 currentCap, uint256 newCap, uint256 effectiveTime);
    event MaxSlippageChangeProposed(uint256 currentSlippage, uint256 newSlippage, uint256 effectiveTime);
    event FeeRateChangeCancelled(uint256 cancelledValue);
    event TargetLtvChangeCancelled(uint256 cancelledValue);
    event BountyRateChangeCancelled(uint256 cancelledValue);
    event DepositCapChangeCancelled(uint256 cancelledValue);
    event MaxSlippageChangeCancelled(uint256 cancelledValue);

    error InvalidFeeRate();
    error InvalidTargetLtv();
    error InvalidBountyRate();
    error InvalidSlippage();
    error InvalidParam();

    /// @notice setParam logic (see Zenji.setParam). Adverse changes timelock; favorable apply now.
    function setParam(
        TimelockLib.TimelockData storage feeT,
        TimelockLib.TimelockData storage ltvT,
        TimelockLib.TimelockData storage capT,
        TimelockLib.TimelockData storage bountyT,
        TimelockLib.TimelockData storage slipT,
        ParamState memory s,
        uint8 p,
        uint256 v,
        uint256 maxTargetLtv,
        uint256 lmMaxBps,
        address yieldStrategy,
        address swapper
    ) public returns (ParamState memory) {
        if (p == 0) {
            if (v > MAX_FEE_RATE) revert InvalidFeeRate();
            if (v > s.feeRate) {
                feeT.propose(v, PARAM_TIMELOCK_DELAY);
                emit FeeRateChangeProposed(s.feeRate, v, block.timestamp + PARAM_TIMELOCK_DELAY);
            } else {
                emit ParamUpdated(p, s.feeRate, v);
                s.feeRate = v;
            }
        } else if (p == 1) {
            if (v < MIN_TARGET_LTV || v > maxTargetLtv) revert InvalidTargetLtv();
            if (lmMaxBps != type(uint256).max && v > lmMaxBps * 1e14) revert InvalidTargetLtv();
            if (v > s.targetLtv) {
                ltvT.propose(v, PARAM_TIMELOCK_DELAY);
                emit TargetLtvChangeProposed(s.targetLtv, v, block.timestamp + PARAM_TIMELOCK_DELAY);
            } else {
                emit ParamUpdated(p, s.targetLtv, v);
                s.targetLtv = v;
            }
        } else if (p == 2) {
            if (v < s.depositCap) {
                capT.propose(v, PARAM_TIMELOCK_DELAY);
                emit DepositCapChangeProposed(s.depositCap, v, block.timestamp + PARAM_TIMELOCK_DELAY);
            } else {
                emit ParamUpdated(p, s.depositCap, v);
                s.depositCap = v;
            }
        } else if (p == 3) {
            if (v > MAX_REBALANCE_BOUNTY) revert InvalidBountyRate();
            if (v > s.rebalanceBountyRate) {
                bountyT.propose(v, PARAM_TIMELOCK_DELAY);
                emit BountyRateChangeProposed(
                    s.rebalanceBountyRate, v, block.timestamp + PARAM_TIMELOCK_DELAY
                );
            } else {
                emit ParamUpdated(p, s.rebalanceBountyRate, v);
                s.rebalanceBountyRate = v;
            }
        } else if (p == 4) {
            if (v < MIN_VAULT_SLIPPAGE || v > MAX_VAULT_SLIPPAGE) revert InvalidSlippage();
            if (v > s.maxSlippage) {
                slipT.propose(v, PARAM_TIMELOCK_DELAY);
                emit MaxSlippageChangeProposed(s.maxSlippage, v, block.timestamp + PARAM_TIMELOCK_DELAY);
            } else {
                emit ParamUpdated(p, s.maxSlippage, v);
                s.maxSlippage = v;
                IYieldStrategy(yieldStrategy).setSlippage(v);
                if (swapper != address(0)) ISwapperSlippage(swapper).setSlippage(v);
            }
        } else {
            revert InvalidParam();
        }
        return s;
    }

    /// @notice executeParamChange logic (see Zenji.executeParamChange). For p==0 the vault must
    ///         call _accrueYieldFees() at the OLD rate BEFORE invoking this (it cannot be done here).
    function executeParamChange(
        TimelockLib.TimelockData storage feeT,
        TimelockLib.TimelockData storage ltvT,
        TimelockLib.TimelockData storage capT,
        TimelockLib.TimelockData storage bountyT,
        TimelockLib.TimelockData storage slipT,
        ParamState memory s,
        uint8 p,
        uint256 maxTargetLtv,
        uint256 lmMaxBps,
        address yieldStrategy,
        address swapper
    ) public returns (ParamState memory) {
        if (p == 0) {
            uint256 newFee = feeT.execute();
            if (newFee > MAX_FEE_RATE) revert InvalidFeeRate();
            emit ParamUpdated(p, s.feeRate, newFee);
            s.feeRate = newFee;
        } else if (p == 1) {
            uint256 newLtv = ltvT.execute();
            if (newLtv < MIN_TARGET_LTV || newLtv > maxTargetLtv) revert InvalidTargetLtv();
            if (lmMaxBps != type(uint256).max && newLtv > lmMaxBps * 1e14) revert InvalidTargetLtv();
            emit ParamUpdated(p, s.targetLtv, newLtv);
            s.targetLtv = newLtv;
        } else if (p == 2) {
            uint256 newCap = capT.execute();
            emit ParamUpdated(p, s.depositCap, newCap);
            s.depositCap = newCap;
        } else if (p == 3) {
            uint256 newBounty = bountyT.execute();
            if (newBounty > MAX_REBALANCE_BOUNTY) revert InvalidBountyRate();
            emit ParamUpdated(p, s.rebalanceBountyRate, newBounty);
            s.rebalanceBountyRate = newBounty;
        } else if (p == 4) {
            uint256 newSlip = slipT.execute();
            if (newSlip < MIN_VAULT_SLIPPAGE || newSlip > MAX_VAULT_SLIPPAGE) revert InvalidSlippage();
            emit ParamUpdated(p, s.maxSlippage, newSlip);
            s.maxSlippage = newSlip;
            IYieldStrategy(yieldStrategy).setSlippage(newSlip);
            if (swapper != address(0)) ISwapperSlippage(swapper).setSlippage(newSlip);
        } else {
            revert InvalidParam();
        }
        return s;
    }

    /// @notice cancelParamChange logic (see Zenji.cancelParamChange).
    function cancelParamChange(
        TimelockLib.TimelockData storage feeT,
        TimelockLib.TimelockData storage ltvT,
        TimelockLib.TimelockData storage capT,
        TimelockLib.TimelockData storage bountyT,
        TimelockLib.TimelockData storage slipT,
        uint8 p
    ) public {
        if (p == 0) {
            emit FeeRateChangeCancelled(feeT.cancel());
        } else if (p == 1) {
            emit TargetLtvChangeCancelled(ltvT.cancel());
        } else if (p == 2) {
            emit DepositCapChangeCancelled(capT.cancel());
        } else if (p == 3) {
            emit BountyRateChangeCancelled(bountyT.cancel());
        } else if (p == 4) {
            emit MaxSlippageChangeCancelled(slipT.cancel());
        } else {
            revert InvalidParam();
        }
    }
}
"
    },
    "src/ZenjiViewHelper.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity ^0.8.33;

import { ILoanManager } from "./interfaces/ILoanManager.sol";
import { IYieldStrategy } from "./interfaces/IYieldStrategy.sol";
import { IERC20 } from "./interfaces/IERC20.sol";

interface IZenjiView {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function getTotalCollateral() external view returns (uint256);
    function loanManager() external view returns (ILoanManager);
    function collateralAsset() external view returns (IERC20);
    function debtAsset() external view returns (IERC20);
    function idle() external view returns (bool);
    function targetLtv() external view returns (uint256);
    function DEADBAND_SPREAD() external view returns (uint256);
    function feeRate() external view returns (uint256);
    function PRECISION() external view returns (uint256);
    function accumulatedFees() external view returns (uint256);
    function lastStrategyBalance() external view returns (uint256);
    function yieldStrategy() external view returns (IYieldStrategy);
    function VIRTUAL_SHARE_OFFSET() external view returns (uint256);
    function strategyDebtRebalanceNeeded() external view returns (bool);
}

/// @title ZenjiViewHelper
/// @notice External helper for view utilities to reduce Zenji bytecode size
contract ZenjiViewHelper {
    function getUserValue(address vault, address user)
        external
        view
        returns (uint256 collateralValue)
    {
        IZenjiView v = IZenjiView(vault);
        uint256 supply = v.totalSupply();
        if (supply == 0) return 0;
        uint256 userShares = v.balanceOf(user);
        uint256 offset = v.VIRTUAL_SHARE_OFFSET();
        return (userShares * (v.getTotalCollateral() + offset)) / (supply + offset);
    }

    function getHealth(address vault) external view returns (int256 health) {
        return IZenjiView(vault).loanManager().getHealth();
    }

    function isRebalanceNeeded(address vault) external view returns (bool needed) {
        IZenjiView v = IZenjiView(vault);
        if (v.strategyDebtRebalanceNeeded()) return true;
        ILoanManager lm = v.loanManager();
        if (!lm.loanExists()) return false;
        uint256 ltv = lm.getCurrentLTV();
        uint256 target = v.targetLtv();
        uint256 deadband = v.DEADBAND_SPREAD();
        return ltv < (target - deadband) || ltv > (target + deadband);
    }

    function getLtvBounds(address vault)
        external
        view
        returns (uint256 lowerBand, uint256 upperBand)
    {
        IZenjiView v = IZenjiView(vault);
        uint256 target = v.targetLtv();
        uint256 deadband = v.DEADBAND_SPREAD();
        lowerBand = target - deadband;
        upperBand = target + deadband;
    }

    function getPendingFees(address vault)
        external
        view
        returns (uint256 totalFees, uint256 pendingFees)
    {
        IZenjiView v = IZenjiView(vault);
        IYieldStrategy strategy = v.yieldStrategy();
        uint256 strategyBalance = strategy.balanceOf();
        uint256 lastBalance = v.lastStrategyBalance();
        if (strategyBalance > lastBalance) {
            uint256 delta = strategyBalance - lastBalance;
            pendingFees = (delta * v.feeRate()) / v.PRECISION();
        }

        totalFees = v.accumulatedFees() + pendingFees;
    }

    /// @notice Get total value in collateral asset units (e.g., WBTC satoshis)
    /// @dev Computes all values natively in collateral terms to avoid double conversion errors
    function getTotalCollateralValue(address vault) external view returns (uint256 totalValue) {
        IZenjiView v = IZenjiView(vault);
        ILoanManager lm = v.loanManager();

        if (v.idle()) {
            return v.collateralAsset().balanceOf(vault);
        }

        // Idle collateral in vault (native units)
        totalValue = v.collateralAsset().balanceOf(vault);

        // Net collateral value in loan manager (collateral - debt in collateral terms)
        totalValue += lm.getNetCollateralValue();

        // Yield strategy balance converted to collateral (excluding fees)
        IYieldStrategy strategy = v.yieldStrategy();
        if (address(strategy) != address(0)) {
            uint256 strategyBalance = strategy.balanceOf();
            uint256 accFees = v.accumulatedFees();
            // Include pending (unaccrued) fees so view stays accurate between accruals
            uint256 lastBalance = v.lastStrategyBalance();
            if (strategyBalance > lastBalance) {
                accFees += (strategyBalance - lastBalance) * v.feeRate() / v.PRECISION();
            }
            if (accFees > strategyBalance) accFees = strategyBalance;
            if (strategyBalance > accFees) {
                totalValue += lm.getDebtValue(strategyBalance - accFees);
            }
        }

        // Idle debt asset in vault converted to collateral
        uint256 idleDebt = v.debtAsset().balanceOf(vault);
        if (idleDebt > 0) {
            totalValue += lm.getDebtValue(idleDebt);
        }

        // Raw collateral in loan manager (not yet supplied)
        totalValue += lm.getCollateralBalance();

        // Raw debt asset in loan manager converted to collateral
        uint256 lmDebt = lm.getDebtBalance();
        if (lmDebt > 0) {
            totalValue += lm.getDebtValue(lmDebt);
        }
    }

    /// @notice Get total value in debt asset units (for diagnostics/logging)
    /// @dev This is a diagnostic function - use getTotalCollateralValue for actual accounting
    function getTotalDebtValue(address vault) external view returns (uint256 totalValue) {
        IZenjiView v = IZenjiView(vault);
        ILoanManager lm = v.loanManager();

        if (v.idle()) {
            return lm.getCollateralValue(v.collateralAsset().balanceOf(vault));
        }

        // Idle collateral converted to debt units
        totalValue = lm.getCollateralValue(v.collateralAsset().balanceOf(vault));

        // Position value in debt terms
        if (lm.loanExists()) {
            (uint256 collateral, uint256 debt) = lm.getPositionValues();
            uint256 collateralInDebt = lm.getCollateralValue(collateral);
            if (collateralInDebt > debt) {
                totalValue += collateralInDebt - debt;
            }
        }

        // Strategy balance (already in debt units, minus fees)
        IYieldStrategy strategy = v.yieldStrategy();
        if (address(strategy) != address(0)) {
            uint256 strategyBalance = strategy.balanceOf();
            uint256 accFees = v.accumulatedFees();
            // Include pending (unaccrued) fees so view stays accurate between accruals
            uint256 lastBalance = v.lastStrategyBalance();
            if (strategyBalance > lastBalance) {
                accFees += (strategyBalance - lastBalance) * v.feeRate() / v.PRECISION();
            }
            if (accFees > strategyBalance) accFees = strategyBalance;
            if (strategyBalance > accFees) {
                totalValue += strategyBalance - accFees;
            }
        }

        // Idle debt in vault
        totalValue += v.debtAsset().balanceOf(vault);

        // Raw collateral in loan manager converted to debt
        uint256 lmCollateral = lm.getCollateralBalance();
        if (lmCollateral > 0) {
            totalValue += lm.getCollateralValue(lmCollateral);
        }

        // Raw debt in loan manager
        totalValue += lm.getDebtBalance();
    }

    function yieldCostBasis(address vault) external view returns (uint256) {
        return IZenjiView(vault).yieldStrategy().costBasis();
    }

    function getYieldStrategyStats(address vault)
        external
        view
        returns (
            string memory strategyName,
            uint256 currentValue,
            uint256 costBasis,
            uint256 unrealizedProfit
        )
    {
        IYieldStrategy strategy = IZenjiView(vault).yieldStrategy();
        strategyName = strategy.name();
        currentValue = strategy.balanceOf();
        costBasis = strategy.costBasis();
        unrealizedProfit = strategy.unrealizedProfit();
    }

    function getYieldVaultStats(address vault)
        external
        view
        returns (
            uint256 yieldShares,
            uint256 currentValue,
            uint256 costBasis,
            uint256 unrealizedProfit
        )
    {
        IYieldStrategy strategy = IZenjiView(vault).yieldStrategy();
        return (0, strategy.balanceOf(), strategy.costBasis(), strategy.unrealizedProfit());
    }
}
"
    },
    "src/ZenjiStorage.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity ^0.8.33;

import { ERC20 } from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import { IERC20 } from "./interfaces/IERC20.sol";
import { IYieldStrategy } from "./interfaces/IYieldStrategy.sol";
import { ILoanManager } from "./interfaces/ILoanManager.sol";
import { ISwapper } from "./interfaces/ISwapper.sol";
import { TimelockLib } from "./libraries/TimelockLib.sol";
import { ZenjiViewHelper } from "./ZenjiViewHelper.sol";
import { ZenjiConstants } from "./libraries/ZenjiConstants.sol";

/// @title ZenjiStorage
/// @notice Canonical storage layout shared by the Zenji vault core and its admin facet.
///         Both inherit this (in the same position) so they agree on every storage slot.
///         Holds the shared STATE declarations plus the shared governance CONSTANTS, which both
///         Zenji and ZenjiAdmin inherit (so `vault.X()` getters and bare `X` references resolve in
///         both, with no duplication). Constants do not occupy storage, so the slot layout is
///         unaffected. Events/errors/modifiers still live in Zenji/ZenjiAdmin (inherited
///         errors/events are not reachable as `Zenji.X`).
abstract contract ZenjiStorage is ERC20 {
    // ============ Shared constants (I-01: single source = ZenjiConstants) ============

    uint256 public constant PRECISION = ZenjiConstants.PRECISION;
    uint256 public constant DEADBAND_SPREAD = ZenjiConstants.DEADBAND_SPREAD;
    uint256 public constant MIN_TARGET_LTV = ZenjiConstants.MIN_TARGET_LTV;
    uint256 public constant MAX_FEE_RATE = ZenjiConstants.MAX_FEE_RATE;
    uint256 public constant COOLDOWN_BLOCKS = ZenjiConstants.COOLDOWN_BLOCKS;
    uint256 public constant MAX_REBALANCE_BOUNTY = ZenjiConstants.MAX_REBALANCE_BOUNTY;
    uint256 public constant TIMELOCK_DELAY = ZenjiConstants.TIMELOCK_DELAY;
    uint256 public constant MAX_VAULT_SLIPPAGE = ZenjiConstants.MAX_VAULT_SLIPPAGE;
    uint256 public constant ROLE_TRANSFER_DELAY = ZenjiConstants.ROLE_TRANSFER_DELAY;
    uint256 public constant GOV_GUARDIAN_TRANSFER_DELAY = ZenjiConstants.GOV_GUARDIAN_TRANSFER_DELAY;
    uint256 public constant PARAM_TIMELOCK_DELAY = ZenjiConstants.PARAM_TIMELOCK_DELAY;
    uint256 public constant EMERGENCY_SKIP_DELAY = ZenjiConstants.EMERGENCY_SKIP_DELAY;
    uint256 public constant GOV_EMERGENCY_DELAY = ZenjiConstants.GOV_EMERGENCY_DELAY;
    uint256 public constant MAX_USER_SLIPPAGE = ZenjiConstants.MAX_USER_SLIPPAGE;

    // ============ Immutables ============

    IERC20 public collateralAsset;
    IERC20 public debtAsset;
    ZenjiViewHelper public viewHelper;
    ILoanManager public loanManager;
    ISwapper public swapper;

    // ============ State ============

    uint256 public targetLtv;
    address public strategist;
    address public gov;
    address public guardian;
    bool public idle;
    bool public emergencyMode;
    bool public liquidationComplete;
    /// @notice Bitmask: bit 0 = step 0 resolved, bit 1 = step 1 resolved.
    /// Both bits must be set (via emergencyStep or emergencySkipStep) before step 2 is allowed.
    uint8 public emergencyStepsCompleted;
    uint256 public accumulatedFees;
    uint256 public feeRate;
    uint256 public lastStrategyBalance;
    uint256 internal _status;
    uint256 internal constant _NOT_ENTERED = 1;
    uint256 internal constant _ENTERED = 2;
    address public pendingStrategist;
    address public pendingGov;
    address public pendingGuardian;
    uint256 public pendingStrategistTimestamp;
    uint256 public pendingGovTimestamp;
    uint256 public pendingGuardianTimestamp;
    uint256 public rebalanceBountyRate;
    uint256 public depositCap;
    uint256 public maxSlippage;
    uint256 public feesAtLastRebalance;
    // Tracks the last block where an address received shares (mint or transfer).
    // Caveat: because any incoming share transfer updates this value, a third party can
    // send dust shares and force a 1-block cooldown on the recipient (dust-grief vector).
    mapping(address => uint256) public lastInBlock;

    // Yield strategy
    IYieldStrategy public yieldStrategy;

    // Timelock state (using TimelockLib)
    TimelockLib.AddressTimelockData internal _swapperTimelock;
    /// @notice Pending feeRate change (only used for adverse i.e. increasing changes)
    TimelockLib.TimelockData internal _feeRateTimelock;
    /// @notice Pending targetLtv change (only used for adverse i.e. increasing changes)
    TimelockLib.TimelockData internal _targetLtvTimelock;
    /// @notice Pending bountyRate / depositCap / maxSlippage increases (adverse changes).
    /// Decreases (or depositCap → 0 which is user-favourable in the pause sense) remain immediate.
    TimelockLib.TimelockData internal _bountyRateTimelock;
    TimelockLib.TimelockData internal _depositCapTimelock;
    TimelockLib.TimelockData internal _maxSlippageTimelock;
    /// @notice Pending change to `rescueRecipient` (gov-set, timelocked address).
    TimelockLib.AddressTimelockData internal _rescueRecipientTimelock;

    /// @notice Guardian-set flag that blocks NEW deposits but leaves withdrawals open.
    /// Separate from `emergencyMode` (one-way liquidation) and `depositCap=0` (overloaded with TVL cap).
    bool public depositsPaused;

    /// @notice Pre-set recipient for guardian-triggered `rescueAssets`. Setting this
    /// removes the "guardian picks where stuck funds go" surface. Gov-managed with 1-week timelock.
    /// Zero is sentinel for "not configured" — rescueAssets reverts until gov initialises.
    address public rescueRecipient;
    /// @notice Pending emergencySkipStep timestamps. Index 0 = step 0 (yield withdraw),
    /// index 1 = step 1 (loan unwind). Zero means no pending skip.
    uint256[2] public pendingSkipTimestamp;

    /// @notice M-06 break-glass: pending gov-proposed emergency-mode entry. Zero means no
    /// pending proposal. Set by govEnterEmergencyMode (first call), consumed by the second
    /// call after GOV_EMERGENCY_DELAY, cleared by cancelGovEmergency (gov or guardian).
    uint256 public pendingGovEmergencyTimestamp;
}
"
    },
    "src/ZenjiAdmin.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity ^0.8.33;

import { ERC20 } from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import { IERC20 } from "./interfaces/IERC20.sol";
import { ISwapper } from "./interfaces/ISwapper.sol";
import { IYieldStrategy } from "./interfaces/IYieldStrategy.sol";
import { ILoanManager } from "./interfaces/ILoanManager.sol";
import { TimelockLib } from "./libraries/TimelockLib.sol";
import { SafeTransferLib } from "./libraries/SafeTransferLib.sol";
import { ZenjiCoreLib } from "./libraries/ZenjiCoreLib.sol";
import { ZenjiStorage } from "./ZenjiStorage.sol";

interface ISwapperGovRotation {
    function transferGovFromVault(address newGov) external;
}

interface ILoanManagerSwapperRotation {
    function proposeSwapper(address newSwapper) external;
    function executeSwapper() external;
    function cancelSwapper() external;
}

/// @title ZenjiAdmin
/// @notice Cold-path admin facet for Zenji (role/swapper/rescue timelocks, emergency, pause).
///         Reached via Zenji's forwarding stubs (delegatecall), runs in the vault's storage
///         (shared ZenjiStorage). msg.sender preserved; events emit from the vault address.
contract ZenjiAdmin is ZenjiStorage {
    using TimelockLib for TimelockLib.AddressTimelockData;
    using TimelockLib for TimelockLib.TimelockData;
    using SafeTransferLib for IERC20;

    constructor() ERC20("", "") { }

    // ============ Constants ============
    // I-01: shared governance constants are declared once in ZenjiStorage (values from
    // ZenjiConstants) and inherited by both Zenji and ZenjiAdmin — no duplication. The public
    // getters and bare references resolve here via inheritance, identical to before.

    // ============ Events ============
    // Keeper actions
    event Rebalance(uint256 oldLtv, uint256 newLtv, bool increased);
    event RebalanceBountyPaid(address indexed keeper, uint256 amount);

    // Capital management
    event CapitalDeployed(uint256 collateralAmount, uint256 debtBorrowed);
    event CapitalUnwound(uint256 collateralNeeded, uint256 collateralReceived);

    // Role transfers
    event StrategistTransferStarted(
        address indexed previousStrategist, address indexed newStrategist
    );
    event StrategistUpdated(address indexed newStrategist);
    event GovernanceTransferStarted(address indexed previousGov, address indexed newGov);
    event GovernanceUpdated(address indexed newGov);
    event GuardianTransferStarted(address indexed previousGuardian, address indexed newGuardian);
    event GuardianUpdated(address indexed newGuardian);
    event IdleModeEntered();
    event IdleModeExited();
    event ParamUpdated(uint8 indexed param, uint256 oldValue, uint256 newValue);
    event FeesWithdrawn(address indexed recipient, uint256 amount);
    event SwapperUpdated(address indexed oldSwapper, address indexed newSwapper);
    event SwapperChangeProposed(
        address indexed currentSwapper, address indexed newSwapper, uint256 effectiveTime
    );
    event SwapperChangeCancelled(address indexed cancelledSwapper);
    // Fee/LTV change events use ParamUpdated above
    event FeeRateChangeProposed(uint256 currentFeeRate, uint256 newFeeRate, uint256 effectiveTime);
    event TargetLtvChangeProposed(uint256 currentLtv, uint256 newLtv, uint256 effectiveTime);
    event BountyRateChangeProposed(uint256 currentRate, uint256 newRate, uint256 effectiveTime);
    event DepositCapChangeProposed(uint256 currentCap, uint256 newCap, uint256 effectiveTime);
    event MaxSlippageChangeProposed(
        uint256 currentSlippage, uint256 newSlippage, uint256 effectiveTime
    );
    event DepositsPaused();
    event DepositsResumed();
    event RescueRecipientChangeProposed(
        address indexed currentRecipient, address indexed newRecipient, uint256 effectiveTime
    );
    event RescueRecipientUpdated(address indexed oldRecipient, address indexed newRecipient);
    event RescueRecipientChangeCancelled(address indexed cancelledRecipient);
    event FeeRateChangeCancelled(uint256 cancelledValue);
    event TargetLtvChangeCancelled(uint256 cancelledValue);
    event BountyRateChangeCancelled(uint256 cancelledValue);
    event DepositCapChangeCancelled(uint256 cancelledValue);
    event MaxSlippageChangeCancelled(uint256 cancelledValue);
    event RoleTransferCancelled(uint8 indexed role, address indexed cancelledAddress);
    event EmergencySkipStepProposed(uint8 indexed step, uint256 effectiveTime);
    event EmergencySkipCancelled(uint8 indexed step);
    event EmergencyModeCancelled();
    event GovEmergencyProposed(uint256 effectiveTime);
    event GovEmergencyCancelled(address indexed canceller);
    event StrategyOwnerPropagationFailed(address indexed newOwner);
    event SwapperGovPropagationFailed(address indexed newGov);

    // Strategy events
    error SwapperUnderperformed(uint256 expected, uint256 received);
    event StrategyDeposit(
        address indexed strategy, uint256 debtAssetAmount, uint256 underlyingDeposited
    );

    // Emergency
    event EmergencyModeEntered();
    event LiquidationComplete(uint256 collateralRecovered, uint256 flashloanAmount);
    event EmergencyStepSkipped(uint8 indexed step);
    event AssetsRescued(address indexed token, address indexed recipient, uint256 amount);
    event FeesAccrued(uint256 profit, uint256 fees, uint256 totalAccumulatedFees);
    event YieldHarvested(address indexed caller, uint256 rewardsValue);
    event EmergencyCollateralTransferred(uint256 amount);
    event EmergencyDebtTransferred(uint256 amount);
    event EmergencyYieldRedeemed(uint256 debtAssetReceived);
    /// @notice Emitted when loan unwinding is attempted in emergency mode
    event EmergencyLoanUnwound(uint256 collateralRecovered, uint256 debtRecovered);

    // ============ Errors ============
    error Unauthorized();
    error ZeroAmount();
    error InsufficientShares();
    error RebalanceNotNeeded();
    error InvalidAddress();
    error AmountTooSmall();
    error ReentrancyError();
    error InvalidFeeRate();
    error InvalidTargetLtv();
    error EmergencyModeActive();
    error EmergencyModeNotActive();
    error InvalidBountyRate();
    error DepositCapExceeded();
    error InvalidStrategy();
    error LiquidationAlreadyComplete();
    error InsufficientCollateral();
    error InsufficientDeposit();
    error InsufficientWithdrawal();
    error EmergencyStepsIncomplete();
    error InvalidEmergencyStep();
    error InvalidSlippage();
    error StrategyDebtCoverageTooLow(uint256 currentRatio, uint256 minRatio);
    error ActionDelayActive();
    error InvalidParam();
    error DepositsArePaused();
    error RescueRecipientNotSet();
    error EmergencyStepInProgress();
    /// @notice Thrown when a user-supplied minAssetsOut floor is not met after unwind.
    error UserSlippageExceeded(uint256 minOut, uint256 actual);

    // ============ Modifiers ============
    modifier onlyStrategist() {
        if (msg.sender != strategist) revert Unauthorized();
        _;
    }

    modifier onlyGov() {
        if (msg.sender != gov) revert Unauthorized();
        _;
    }

    modifier onlyGuardian() {
        if (msg.sender != guardian) revert Unauthorized();
        _;
    }

    modifier nonReentrant() {
        if (_status == _ENTERED) revert ReentrancyError();
        _status = _ENTERED;
        _;
        _status = _NOT_ENTERED;
    }

    // ============ Cold-path admin (delegatecalled from Zenji) ============

    /// @notice Propose a new swapper contract (requires timelock).
    /// @dev Gov-only. 1-week timelock for critical infrastructure changes. The proposal
    ///      is mirrored on the loan manager so that the loan-manager-side swapper
    ///      (used by the Aave flash-unwind path) stays in lockstep with the vault.
    function proposeSwapper(address newSwapper) external onlyGov {
        if (newSwapper == address(0)) revert InvalidAddress();
        if (newSwapper == address(swapper)) revert InvalidAddress();
        _swapperTimelock.proposeAddress(newSwapper, TIMELOCK_DELAY);
        ILoanManagerSwapperRotation(address(loanManager)).proposeSwapper(newSwapper);
        emit SwapperChangeProposed(address(swapper), newSwapper, _swapperTimelock.timestamp);
    }

    /// @notice Execute pending swapper change after timelock. Updates both the vault's
    ///         own swapper reference and the loan manager's reference atomically.
    function executeSwapper() external onlyGov {
        address oldSwapper = address(swapper);
        swapper = ISwapper(_swapperTimelock.executeAddress());
        ILoanManagerSwapperRotation(address(loanManager)).executeSwapper();
        emit SwapperUpdated(oldSwapper, address(swapper));
    }

    /// @notice Cancel pending swapper change (cancels both vault and loan manager).
    function cancelSwapper() external onlyGov {
        address cancelled = _swapperTimelock.cancelAddress();
        ILoanManagerSwapperRotation(address(loanManager)).cancelSwapper();
        emit SwapperChangeCancelled(cancelled);
    }

    /// @notice Transfer role: 0=strategist, 1=gov, 2=guardian (only gov can initiate all transfers)
    /// @dev Starts a timelock; new address must call acceptRole after the delay.
    ///      Strategist uses ROLE_TRANSFER_DELAY (1 week). Gov and guardian use the
    ///      extended GOV_GUARDIAN_TRANSFER_DELAY (4 weeks) — these roles are powerful
    ///      enough that a compromised gov should not be able to short-circuit the
    ///      veto window with a quick handover.
    function transferRole(uint8 role, address to) external onlyGov {
        if (to == address(0)) revert InvalidAddress();
        // Gov and guardian transfers must be sequential — concurrent queuing would let a
        // compromised gov force guardian to cancel two transfers simultaneously, shrinking
        // the effective veto window. Each transfer must complete or be cancelled first.
        if (role == 1 && pendingGuardianTimestamp != 0) revert ActionDelayActive();
        if (role == 2 && pendingGovTimestamp != 0) revert ActionDelayActive();
        if (role == 0) {
            pendingStrategist = to;
            pendingStrategistTimestamp = block.timestamp + ROLE_TRANSFER_DELAY;
            emit StrategistTransferStarted(strategist, to);
        } else if (role == 1) {
            pendingGov = to;
            pendingGovTimestamp = block.timestamp + GOV_GUARDIAN_TRANSFER_DELAY;
            emit GovernanceTransferStarted(gov, to);
        } else {
            pendingGuardian = to;
            pendingGuardianTimestamp = block.timestamp + GOV_GUARDIAN_TRANSFER_DELAY;
            emit GuardianTransferStarted(guardian, to);
        }
    }

    /// @notice Accept role: 0=strategist, 1=gov, 2=guardian
    /// @dev Caller must be the pending address and 2-day timelock must have passed.
    function acceptRole(uint8 role) external {
        if (role == 0) {
            if (msg.sender != pendingStrategist) revert Unauthorized();
            if (block.timestamp < pendingStrategistTimestamp) {
                revert TimelockLib.TimelockNotReady();
            }
            strategist = msg.sender;
            pendingStrategist = address(0);
            pendingStrategistTimestamp = 0;
            emit StrategistUpdated(msg.sender);
        } else if (role == 1) {
            if (msg.sender != pendingGov) revert Unauthorized();
            if (block.timestamp < pendingGovTimestamp) revert TimelockLib.TimelockNotReady();
            gov = msg.sender;
            pendingGov = address(0);
            pendingGovTimestamp = 0;
            emit GovernanceUpdated(msg.sender);
            // M-02: propagate ownership to the strategy ATOMICALLY — no try/catch. If the
            // strategy can't accept the new owner, the entire rotation reverts so vault.gov
            // can never diverge from strategy.owner. The previous try/catch swallowed the
            // failure, leaving a rotated-away key with rescueERC20 / setSlippage authority and
            // no on-chain re-sync path. A paused/bricked strategy must be made transferable
            // before gov can rotate — preferred over a silent, permanent split.
            yieldStrategy.transferOwnerFromVault(msg.sender);
            // Swapper gov handoff stays best-effort: the swapper is mutable via its own 1-week
            // timelock (a stale swapper can simply be rotated out), and not every registered
            // swapper implements vault-initiated gov rotation, so it must not block the handoff.
            try ISwapperGovRotation(address(swapper)).transferGovFromVault(msg.sender) {
            // success — swapper gov is now the new gov
            }
            catch {
                emit SwapperGovPropagationFailed(msg.sender);
            }
        } else {
            if (msg.sender != pendingGuardian) revert Unauthorized();
            if (block.timestamp < pendingGuardianTimestamp) revert TimelockLib.TimelockNotReady();
            guardian = msg.sender;
            pendingGuardian = address(0);
            pendingGuardianTimestamp = 0;
            emit GuardianUpdated(msg.sender);
        }
    }

    /// @notice Cancel a pending role transfer (Gov-only)
    function cancelRole(uint8 role) external onlyGov {
        _cancelRole(role);
    }

    /// @notice Guardian veto on a pending role transfer.
    /// @dev Allows guardian to block a malicious role transfer scheduled by a
    ///      compromised gov. Without this, a compromised gov could schedule a
    ///      guardian/strategist replacement and only gov could cancel it —
    ///      meaning the legitimate guardian had no on-chain recourse.
    function guardianCancelRole(uint8 role) external onlyGuardian {
        _cancelRole(role);
    }

    function _cancelRole(uint8 role) internal {
        address cancelled;
        if (role == 0) {
            cancelled = pendingStrategist;
            if (cancelled == address(0)) revert TimelockLib.NoTimelockPending();
            pendingStrategist = address(0);
            pendingStrategistTimestamp = 0;
        } else if (role == 1) {
            cancelled = pendingGov;
            if (cancelled == address(0)) revert TimelockLib.NoTimelockPending();
            pendingGov = address(0);
            pendingGovTimestamp = 0;
        } else if (role == 2) {
            cancelled = pendingGuardian;
            if (cancelled == address(0)) revert TimelockLib.NoTimelockPending();
            pendingGuardian = address(0);
            pendingGuardianTimestamp = 0;
        } else {
            revert InvalidParam();
        }
        emit RoleTransferCancelled(role, cancelled);
    }

    /// @notice Guardian veto on a pending swapper change.
    /// @dev If gov is compromised, gov could propose a malicious swapper. Without
    ///      this veto only gov could cancel it. Guardian can now block the change
    ///      during the 1-week timelock window.
    function guardianCancelSwapper() external onlyGuardian {
        address cancelled = _swapperTimelock.cancelAddress();
        ILoanManagerSwapperRotation(address(loanManager)).cancelSwapper();
        emit SwapperChangeCancelled(cancelled);
    }

    /// @notice Enter emergency mode - one-way latch, no exit
    /// @dev Guardian-only. Blocks deposits permanently. Withdrawals resume after liquidation completes.
    function enterEmergencyMode() external onlyGuardian {
        _enterEmergencyMode();
    }

    /// @notice M-06 break-glass: gov can enter emergency mode behind a 48h timelock.
    /// @dev Two-call pattern (mirrors emergencySkipStep): first call proposes, second call after
    ///      GOV_EMERGENCY_DELAY executes. Covers guardian key loss — without this, the vault has
    ///      no emergency response for the 4-week guardian rotation (deposits keep flowing into a
    ///      potentially compromised strategy). Scope is deliberately minimal: gov only gains
    ///      ENTRY (a defensive stop — blocks deposits/harvest/rebalance/withdrawFees); the
    ///      emergency steps stay guardian-only so a compromised gov cannot force a lossy
    ///      skip-skip-liquidate (gov is the only skip veto, so it must not also hold the steps).
    ///      A live guardian (or gov itself) can veto the proposal via cancelGovEmergency during
    ///      the 48h window; an unwanted executed entry is still reversible via
    ///      cancelEmergencyMode before any step runs.
    function govEnterEmergencyMode() external onlyGov {
        if (emergencyMode) revert EmergencyModeActive();
        uint256 pending = pendingGovEmergencyTimestamp;
        if (pending == 0) {
            pendingGovEmergencyTimestamp = block.timestamp + GOV_EMERGENCY_DELAY;
            emit GovEmergencyProposed(pendingGovEmergencyTimestamp);
        } else {
            if (block.timestamp < pending) revert TimelockLib.TimelockNotReady();
            pendingGovEmergencyTimestamp = 0;
            _enterEmergencyMode();
        }
    }

    /// @notice Veto a pending gov emergency-mode proposal.
    /// @dev Callable by guardian (counter to a compromised gov) or gov (changed its mind).
    function cancelGovEmergency() external {
        if (msg.sender != gov && msg.sender != guardian) revert Unauthorized();
        if (pendingGovEmergencyTimestamp == 0) revert TimelockLib.NoTimelockPending();
        pendingGovEmergencyTimestamp = 0;
        emit GovEmergencyCancelled(msg.sender);
    }

    function _enterEmergencyMode() internal {
        if (emergencyMode) revert EmergencyModeActive();
        emergencyMode = true;
        // A pending gov proposal is moot once emergency mode is active.
        pendingGovEmergencyTimestamp = 0;
        emit EmergencyModeEntered();
    }

    /// @notice Emergency step: 0=withdrawYield, 1=unwindLoan, 2=completeLiquidation
    function emergencyStep(uint8 step) external nonReentrant onlyGuardian {
        if (step > 2) revert InvalidEmergencyStep();
        if (!emergencyMode) revert EmergencyModeNotActive();
        if (liquidationComplete) revert LiquidationAlreadyComplete();
        // Step 2: requires both prior steps to be resolved (run or explicitly skipped)
        if (step == 2 && emergencyStepsCompleted & 0x3 != 0x3) revert EmergencyStepsIncomplete();

        (uint256 newLSB, uint256 newFees, bool setLiq, bool yieldWithdrawn) = ZenjiCoreLib.executeEmergencyStep(
            step,
            yieldStrategy,
            loanManager,
            collateralAsset,
            debtAsset,
            swapper,
            lastStrategyBalance,
            accumulatedFees
        );

        lastStrategyBalance = newLSB;
        accumulatedFees = newFees;
        if (setLiq) liquidationComplete = true;

        if (step == 0) {
            feesAtLastRebalance = 0;
            // Only mark step 0 complete when the strategy exit ran to completion (or no strategy
            // exists). A clean 0-return from an already-empty strategy counts as complete. If
            // both withdrawAll() and emergencyWithdraw() reverted (e.g. oracle stale), leave the
            // bit clear so the guardian can retry after the oracle recovers, or explicitly skip.
            if (yieldWithdrawn) emergencyStepsCompleted |= 0x1;
